def permutation(lst, s):
    if len(lst) == 1:
        return s
    else:
        perm_list = [] 
        for y in permutation(lst[:-1], s): # recursive call 
            for x in lst:
                if x not in y: # check if element is already in permutation
                    perm_list.append(y+x)
        return perm_list
```

