def all_subsets(s):
    subsets = []
    for i in range(2**len(s)):
        bitmask = bin(i)[2:]
        subset = []
        for j in range(len(s)):
            if bitmask[j] == "1":
                subset.append(s[j])
        subsets.append(subset)
    return subsets
