# shapes_lib.py
class Shape:
    """Base class for creating shapes."""

    def __init__(self, sides, *args):
        self.sides = sides

class Circle(Shape):
    """A circle with a fixed radius."""

    def __init__(self, radius):
        super().__init__(1)
        self.radius = radius

    def area(self):
        return 3.14 * (self.radius ** 2)

class Triangle(Shape):
    """A triangle with sides of varying lengths."""

    def __init__(self, side1, side2, side3):
        super().__init__(3)
        self.side1 = side1
        self.side2 = side2
        self.side3 = side3

    def area(self):
        s = (self.side1 + self.side2 + self.side3) / 2
        return (s * (s - self.side1) * (s - self.side2) * (s - self.side3)) ** 0.5

class Square(Shape):
    """A square with four equal sides."""

    def __init__(self, side):
        super().__init__(4)
        self.side = side

    def area(self):
        return self.side**2

def restore_shape(shape_data):
    shape_type = shape_data[\'type\']
    if shape_type == \'circle\':
        return Circle(shape_data[\'radius\'])
    elif shape_type == \'triangle\':
        return Triangle(shape_data[\'side1\'], shape_data[\'side2\'], shape_data[\'side3\'])
    elif shape_type == \'square\':
        return Square(shape_data[\'side\'])
