def list_organizer(list_of_strings):
    words_2_vowels = []
    words_1_vowel_or_none = []
    vowels = ["a", "e", "i", "o", "u"]

    for word in list_of_strings:
        count = 0
        for char in word:
            if char in vowels:
                count += 1
        if count >= 2:
            words_2_vowels.append(word)
        else:
            words_1_vowel_or_none.append(word)

    return (words_2_vowels, words_1_vowel_or_none)
